// Simple Markdown mode for CodeMirror 5
CodeMirror.defineMode("markdown", function(cmCfg, modeCfg) {
  return {
    startState: function() {
      return {
        inCodeBlock: false,
        inInlineCode: false,
        inLink: false,
        headerLevel: 0
      };
    },
    token: function(stream, state) {
      // Code blocks
      if (stream.sol() && stream.match(/^```/)) {
        state.inCodeBlock = !state.inCodeBlock;
        return "comment";
      }
      if (state.inCodeBlock) {
        stream.skipToEnd();
        return "comment";
      }

      // Headers
      if (stream.sol() && stream.match(/^#{1,6}/)) {
        stream.skipToEnd();
        return "header";
      }

      // Bold
      if (stream.match(/\*\*/)) {
        return "strong";
      }

      // Italic
      if (stream.match(/\*/)) {
        return "em";
      }

      // Inline code
      if (stream.match(/`/)) {
        if (!state.inInlineCode) {
          state.inInlineCode = true;
          return "comment";
        } else {
          state.inInlineCode = false;
          return "comment";
        }
      }
      if (state.inInlineCode) {
        stream.next();
        return "comment";
      }

      // Links
      if (stream.match(/\[.*?\]\(.*?\)/)) {
        return "link";
      }

      // Lists
      if (stream.sol() && (stream.match(/^\s*[\*\-\+]\s/) || stream.match(/^\s*\d+\.\s/))) {
        return "string";
      }

      stream.next();
      return null;
    }
  };
});

CodeMirror.defineMIME("text/x-markdown", "markdown");